  async dispose(): Promise<void> {
    this.disposed = true
    await this.mutation
    const attempt = this.active
    if (attempt !== undefined && attempt.winner === undefined) {
      await this.cancel(attempt.id)
    } else if (attempt !== undefined) {
      await attempt.done
    }
  }
}
